sys_script_client.script:
function onSubmit() {
    var packageLpa = g_form.getValue('package_lpa');
    var maxStudents = g_form.getValue('max_students');
    var driveDate = g_form.getValue('date');
    var regDeadline = g_form.getValue('registration_deadline');

    g_form.clearMessages();

    // 1. Validate Package LPA positive
    if (packageLpa) {
        var numPackage = parseFloat(packageLpa.replace(/[^0-9.-]+/g, ''));
        if (isNaN(numPackage) || numPackage <= 0) {
            g_form.addErrorMessage('Package LPA must be greater than zero.');
            g_form.showFieldMsg('package_lpa', 'Package LPA must be positive.', 'error');
            return false;
        }
    }

    // 2. Validate Max Students positive
    if (maxStudents) {
        var numStudents = parseInt(maxStudents, 10);
        if (isNaN(numStudents) || numStudents <= 0) {
            g_form.addErrorMessage('Max Students must be greater than zero.');
            g_form.showFieldMsg('max_students', 'Max Students must be positive.', 'error');
            return false;
        }
    }

    // 3. Validate Date after Registration Deadline
    if (driveDate && regDeadline) {
        var deadlineDate = regDeadline.split(' ')[0];
        if (driveDate <= deadlineDate) {
            g_form.addErrorMessage('Placement Drive Date must be after the Registration Deadline.');
            g_form.showFieldMsg('date', 'Drive Date must be after Registration Deadline (' + deadlineDate + ').', 'error');
            return false;
        }
    }

    return true;
}
